import Foundation

/// The curated, bundled geography dataset. A pure static array of value types —
/// no networking, no SwiftData. Capitals and continents are hand-checked.
/// Population figures are rounded millions and are intentionally approximate
/// (they only drive the "bigger population" mode and detail copy).
enum CountryData {

    /// All countries, sorted by name for stable presentation.
    static let all: [Country] = raw.sorted { $0.name < $1.name }

    /// Quick lookup by ISO-2 code.
    static let byCode: [String: Country] = {
        Dictionary(uniqueKeysWithValues: raw.map { ($0.iso2, $0) })
    }()

    static func country(for iso2: String) -> Country? { byCode[iso2] }

    static func countries(in continent: Continent) -> [Country] {
        all.filter { $0.continent == continent }
    }

    static func count(in continent: Continent) -> Int {
        raw.lazy.filter { $0.continent == continent }.count
    }

